const GENERIC_SVG =
  '<path d="M12 2 3 7v10l9 5 9-5V7zm0 2.31L18.5 8 12 11.69 5.5 8zM5 9.72l6 3.41v6.15l-6-3.33zm14 0v6.23l-6 3.33v-6.15z"/>'

// 判定规则见 utils/modelVendor.ts——那里是全站唯一一份，
// 在线使用页的分组下拉与模型广场的分组都用它，避免多处各写一遍后互相漂移。
const brand = computed<Brand>(() => {
  const v = resolveModelVendor(props.model)
  return {
    key: v.key,
    label: LABELS[v.key] ?? v.label,
    svg: ICONS[v.key] ?? GENERIC_SVG,
    bg: COLORS[v.key] ?? '#94A3B8',
    fg: '#FFFFFF'
  }
})

const sizeClass = computed(() =>
  props.size === 'sm' ? 'h-5 w-5' : props.size === 'lg' ? 'h-10 w-10' : 'h-6 w-6'
)
const glyphClass = computed(() =>
  props.size === 'sm' ? 'h-3 w-3' : props.size === 'lg' ? 'h-6 w-6' : 'h-3.5 w-3.5'
)
</script>
